create table product_faqs (id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,sku_id uuid references skus(id) on delete cascade,question text not null,answer text not null,category text,source text not null default 'ai_draft',verified boolean not null default false,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table content_assets (id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,sku_id uuid references skus(id) on delete cascade,sku_code text,type text not null,title text,content_json jsonb not null,ai_run_id uuid references ai_runs(id) on delete set null,status text not null default 'draft',created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create index content_assets_user_created_idx on content_assets(user_id,created_at desc);create index product_faqs_sku_idx on product_faqs(sku_id,verified);
alter table product_faqs enable row level security;alter table content_assets enable row level security;
create policy "own faqs" on product_faqs for all using(user_id=auth.uid()) with check(user_id=auth.uid());create policy "own content" on content_assets for all using(user_id=auth.uid()) with check(user_id=auth.uid());
